const sketch = (p5obj:any) => {
/**

ボールのキャラクターの動きと時刻の進みが連動している時計
時間、分、秒が切り替わる時に、キャラクターが各自の時間ボックスを叩く

*/

let iHour: number; //現在の時間
let iAnimFrameH: number; // アニメーションフレーム（時間）
let iMinute: number; //現在の分
let iAnimFrameM: number; // アニメーションフレーム（分）
let iSecond: number; // 現在の秒
let iAnimFrameS: number; // アニメーションフレーム（秒）

p5obj.setup = () => 
{
  p5obj.createCanvas(400,250);
  p5obj.frameRate( 20 );
  iHour = p5obj.hour();
  iMinute = p5obj.minute();
  iSecond = p5obj.second();
  iAnimFrameH = 0;
  iAnimFrameM = 0;
  iAnimFrameS = 0;
}

p5obj.draw = () => 
{
  // スクリーンリフレッシュ
  p5obj.noStroke();
  p5obj.fill( 201, 201, 201 ); // 背景色（灰色）
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );
  // 地面の色
  p5obj.fill(256,256,256);
  p5obj.rect(0,215,400,215);
  p5obj.stroke( 0 );
  // 地面の描画
  p5obj.line(0,215,400,215);
  
  // ブロックの描画
    // 時間の矩形アニメーション描画
  let fHourRectY: number = 40; // 跳ねる矩形の初期Y座標値
  /** アニメーションは3フレーム目に開始して8フレーム目で終了 */
  if( iAnimFrameH > 3 && iAnimFrameH < 8 )
  {
    fHourRectY -= 10 * p5obj.sin( p5obj.radians( 180 * ( iAnimFrameH - 3 ) / 5.0 ) );
  }
  p5obj.fill(256,256,256); //　矩形の色
  p5obj.rect(70,fHourRectY,60,60);
  p5obj.fill( 0 );
  p5obj.textSize( 20 );
  p5obj.textAlign(p5obj.CENTER);
  p5obj.text( iHour, 70+31, fHourRectY+36 );
  p5obj.noFill();
  
   // 分の矩形アニメーション描画
  let fMinuteRectY: number = 40; // 跳ねる矩形の初期Y座標値
  /** アニメーションは3フレーム目に開始して8フレーム目で終了 */
  if( iAnimFrameM > 3 && iAnimFrameM < 8 )
  {
    fMinuteRectY -= 10 * p5obj.sin( p5obj.radians( 180 * ( iAnimFrameM - 3 ) / 5.0 ) );
  }
  p5obj.fill(256,256,256); //　矩形の色
  p5obj.rect(170,fMinuteRectY,60,60);
  p5obj.fill( 0 );
  p5obj.textSize( 20 );
  p5obj.textAlign(p5obj.CENTER);
  p5obj.text( iMinute, 170+31, fMinuteRectY+36 );
  p5obj.noFill();
 
  // 秒の矩形アニメーション描画
  let fSecondRectY: number = 40; // 跳ねる矩形の初期Y座標値
  /** アニメーションは3フレーム目に開始して8フレーム目で終了 */
  if( iAnimFrameS > 3 && iAnimFrameS < 8 )
  {
    fSecondRectY -= 10 * p5obj.sin( p5obj.radians( 180 * ( iAnimFrameS - 3 ) / 5.0 ) );
  }
  p5obj.fill(256,256,256); //　矩形の色
  p5obj.rect( 270, fSecondRectY, 60, 60 );
  p5obj.fill( 0 );
  p5obj.textSize( 20 );
  p5obj.textAlign(p5obj.CENTER);
  p5obj.text( iSecond, 270+31, fSecondRectY+36 );
  p5obj.noFill();
  
  // 時間の楕円
  //時間のアニメーション描画
  let fHourEllipseY: number = 200; // ジャンプする楕円の初期Y座標値
  /** アニメーションは8フレームの間行う．
  8フレームを超えたら初期位置で待機． */
  if( iAnimFrameH < 8 )
  {
    fHourEllipseY -= 90 * p5obj.sin( p5obj.radians( 180 * iAnimFrameH / 8.0 ) );
  }
  p5obj.fill(76,113,71); //　緑色
  p5obj.ellipse( 100, fHourEllipseY, 30, 30 );
  //　白目（時間）
  p5obj.fill(256,256,256);
  p5obj.ellipse(93,fHourEllipseY,7,7);
  p5obj.ellipse(107,fHourEllipseY,7,7);
  //　黒目（時間）
  p5obj.fill(0);
  p5obj.ellipse(93,fHourEllipseY,3,3);
  p5obj.ellipse(107,fHourEllipseY,3,3);
  // 最新の時間取得
  let iHourNew: number = p5obj.hour();
  // アニメーションフレーム（時間）更新
  if( iHour != iHourNew )
  {
    iHour = iHourNew;
    iAnimFrameH = 0;
  }
  else if( iAnimFrameH < 8 )
  {
    iAnimFrameH++;
  }
  
  // 分の楕円
  //分のアニメーション描画
  let fMinuteEllipseY: number = 200; // ジャンプする楕円の初期Y座標値
  /** アニメーションは8フレームの間行う．
  8フレームを超えたら初期位置で待機． */
  if( iAnimFrameM < 8 )
  {
    fMinuteEllipseY -= 90 * p5obj.sin( p5obj.radians( 180 * iAnimFrameM / 8.0 ) );
  }
  p5obj.fill(240,222,58); //　黄色
  p5obj.ellipse( 200, fMinuteEllipseY, 30, 30 );
  //　白目（分）
  p5obj.fill(256,256,256);
  p5obj.ellipse(93+100,fMinuteEllipseY,7,7);
  p5obj.ellipse(107+100,fMinuteEllipseY,7,7);
  //　黒目（分）
  p5obj.fill(0);
  p5obj.ellipse(93+100,fMinuteEllipseY,3,3);
  p5obj.ellipse(107+100,fMinuteEllipseY,3,3);
  // 最新の時間取得
  let iMinuteNew: number = p5obj.minute();
  // アニメーションフレーム（分）更新
  if( iMinute != iMinuteNew )
  {
    iMinute = iMinuteNew;
    iAnimFrameM = 0;
  }
  else if( iAnimFrameM < 8 )
  {
    iAnimFrameM++;
  }
  
  // 秒の楕円アニメーション描画
  let fSecondEllipseY: number = 200; // ジャンプする楕円の初期Y座標値
  /** アニメーションは8フレームの間行う．
  8フレームを超えたら初期位置で待機． */
  if( iAnimFrameS < 8 )
  {
    fSecondEllipseY -= 90 * p5obj.sin( p5obj.radians( 180 * iAnimFrameS / 8.0 ) );
  }
  p5obj.fill(216,86,63); //　赤色
  p5obj.ellipse( 300, fSecondEllipseY, 30, 30 );
  //　白目（秒）
  p5obj.fill(256,256,256);
  p5obj.ellipse(93+200,fSecondEllipseY,7,7);
  p5obj.ellipse(107+200,fSecondEllipseY,7,7);
  //　黒目（秒）
  p5obj.fill(0);
  p5obj.ellipse(93+200,fSecondEllipseY,3,3);
  p5obj.ellipse(107+200,fSecondEllipseY,3,3);
  // 最新の時間取得
  let iSecondNew: number = p5obj.second();
  // アニメーションフレーム（秒）更新
  if( iSecond != iSecondNew )
  {
    iSecond = iSecondNew;
    iAnimFrameS = 0;
  }
  else if( iAnimFrameS < 8 )
  {
    iAnimFrameS++;
  }
}

};

export default sketch;
