const sketch = (p:any) => {
    p.setup = () => {
p.createCanvas(500, 500);      // Window Size
p.colorMode(p.RGB, 1.0); // RGB(0.0~1.0)
var fR, fG, fB;      // Window RGB
for (var iX=0; iX<p.width; iX++)
{
  for (var iY=0; iY<p.height; iY++)
  {
    fR=p.tan(iY+10)*p.tan(iX+10);
    fG=0.1/((p.pow(iX-250, 2)/iY+p.pow(iY+250, 1))+p.sin(p.radians(iY*100)))+(p.sin(iX+iX))+p.cos(iY/10.0)+p.cos(iX/10.0)+p.tan(iY/50.0);
    fB=p.sin(iY/10.0)+p.sin(iX/10.0)+(p.pow(iX-250, 2)+p.pow(iY+250, 2));

    p.stroke(fR, fG, fB);
    p.point(iX, iY);
  }
}

  };
};

export default sketch;
