const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(0);
p5obj.noStroke();
p5obj.fill(255, 255, 0);
var c;
for (var a = 25; a <= 500; a += 50)
{
  for (var b = 25; b <= 500; b += 50)
  {
    c = p5obj.random(0, 360);
    p5obj.arc(a, b, 40, 40, p5obj.radians(c), p5obj.radians(c+300));
  }
}

  };
};

export default sketch;
