// ContentFrame.tsx

import React, { useState, useEffect, useRef } from 'react';
import { BaseContentProps } from './Content';
import './ContentFrame.css';

interface ContentFrameProps {
  componentPrefix: string;
  navigateRoot: string;
  binFolder: string
  anchorTag: string;
  param?: string;
}


const ContentFrame: React.FC<ContentFrameProps> = ({ componentPrefix, navigateRoot, binFolder, anchorTag, param }) => {
  const componentName = useRef<string>();
  const DynamicComponent  = useRef<any>(undefined);
//  const [ showComponent, setShowComponent ] = useState<boolean>(true);
//  const [ contentProps, setContentProps ] = useState<BaseContentProps>();

  let lessonId: string ='';
  let practiceId: string ='';

  console.log(`param in ContentFrame: ${param}`);
  if (param !== undefined) {
    [lessonId, practiceId] = param.split('-');
  }

  // コンテンツの引数
  let lContentProps: BaseContentProps = {
    compId: parseInt(lessonId),
    secId: parseInt(practiceId),
    navigateRoot: navigateRoot,
    anchorTag: anchorTag,
    binFolder: binFolder };

  //setContentProps(lContentProps);


  // LessonIndex を最大2桁の数字として生成
  let formattedLessonId = lessonId.padStart(2, '0');

  // コンポーネントの名前を生成
  let lcomponentName = `${componentPrefix}${formattedLessonId}`;
  console.log(`lcomponentName, componentName.current : ContentFrame: ${lcomponentName}, ${componentName.current}` );

  // コンポーネントが変わるか
  if( componentName.current !== lcomponentName )
  {
    console.log(`requare in ContentFrame:${lcomponentName}`);
    componentName.current = lcomponentName;
    console.log(`componentName.current : ContentFrame: ${componentName.current}` );


    const dynamicComponentSrc = require(`${lcomponentName}`);
    DynamicComponent.current = dynamicComponentSrc.default;  
  }
    

  // コンポーネントが正しく読み込まれた場合、セットする
  //setDynamicComponent(lDynamicComponent);

  //console.log('DynamicComponent in ContentFrame:', dynamicComponentSrc.toString() );
  //setShowComponent(false);
  //setDynamicComponent(lDynamicComponent);
  //}

  return (
    <div className="content-frame">
        {(DynamicComponent.current !== undefined) && <DynamicComponent.current {...lContentProps} />}
    </div>
  );
};

export default ContentFrame;
