const sketch = (p5obj:any) => {
/* 菴懷刀讎りｦ・*/
/*
 繧ｵ繧､繝ｳ髢｢謨ｰ縺ｫ繧医ｋ譎りｨ医〒縺ゅｋ縲ゆｸｻ縺ｪ迚ｹ蠕ｴ縺ｯ莉･荳九・騾壹ｊ縲・
 (i) 遘偵・繧ｵ繧､繝ｳ譖ｲ邱壹→逶ｴ邱壹・蜍輔″縺ｫ繧医▲縺ｦ騾｣邯夂噪縺ｫ陦ｨ迴ｾ縺励※縺・ｋ縲らｧ呈焚縺悟・繧頑崛繧上ｋ縺ｨ縺阪∵峇邱壹→逶ｴ邱壹′縺｡繧・≧縺ｩ莠､繧上ｋ繧医≧縺ｫ險ｭ險医＠縺溘・螻ｱ1遘偵・
 (ii) 蛻・・繧ｵ繧､繝ｳ譖ｲ邱壹→髱｢縺ｫ繧医▲縺ｦ陦ｨ縺励◆縲る擇縺ｯ蟆代＠縺壹▽蠅怜刈縺励※縺・″縲・螻ｱ縺ゅ◆繧・0蛻・°縺代※謠上￥縲・0蛻・ｵ後▽縺ｨ縺ｯ縺倥ａ縺ｫ謌ｻ繧九よ峇邱壹・蝗ｺ螳壹・
 (iii) 譎る俣縺ｯ閭碁擇縺ｮ遏ｩ蠖｢縺ｮ蟷・→蟇ｾ蠢懊＠縺ｦ縺・ｋ縲・蛻・★縺､讓ｪ蟷・′蠅怜刈縺励・4譎る俣縺ｧ蛻・ｊ譖ｿ繧上ｋ縲・
 
 (iv) 遏ｩ蠖｢縺ｮ濶ｲ縺ｯ遨ｺ縺ｮ濶ｲ蜻ｳ縺ｫ蜷医ｏ縺帙◆縲ゅ∪縺溽洸蠖｢縺ｮ閭梧勹縺ｯ縲∵仂縺ｫ譏弱ｋ縺上∝､懊↓證励￥縺ｪ繧九ｈ縺・ｪｿ謨ｴ縺励◆縲ょ盾閠・↓縺励◆縺薙ｈ縺ｿ縺ｯ2023/06/05縺ｧ縺ゅｋ縲・
 (v) (ii)縺ｮ謠冗判濶ｲ縺ｯ閭梧勹濶ｲ縺ｨ縺翫♀繧医◎濶ｲ縺悟渚霆｢縺吶ｋ繧医≧縺ｫ縺励◆縲ゅ◆縺ｨ縺医・縲∵ｷｱ螟・譎ゅ↑繧峨・(ii)縺ｮ繧ｰ繝ｩ繝輔・逋ｽ縺乗緒縺九ｌ繧九′縲∬レ譎ｯ濶ｲ縺ｯ證励＞縲ょ壕蜑・0譎ゅ↑繧・ii)縺梧囓縺・牡縲∬レ譎ｯ濶ｲ縺ｯ逋ｽ縺ｫ霑代＞濶ｲ縺ｨ縺ｪ繧九・
 
 (vi) 1譎る俣縺斐→縺ｫ譎ょｱ繧､繝吶Φ繝医′逋ｺ逕溘☆繧九・
 (a) dBoyWave(): 繝・ュ縺上ｓ縺溘■縺梧ｳ｢縺ｮ繧医≧縺ｫ迴ｾ繧後ｋ縲ら匱逕溽｢ｺ邇・0%縲・
 (b) dBoyBoss(): 螟ｧ縺阪↑繝・ュ縺上ｓ縺後％縺｡繧峨ｒ隕九▽繧√※豬√ｌ縺ｦ縺・￥縲ら匱逕溽｢ｺ邇・0%縲・
 (c) dBoySpiral(): 荳・牡縺ｫ譏取ｻ・☆繧・000縺ｮ繝・ュ縺上ｓ縺溘■縺瑚楴譌九ｒ謠上＞縺ｦ縺ｯ蜴ｻ縺｣縺ｦ縺・￥縲ら匱逕溽｢ｺ邇・0%縲・
 */


let x: number[];
let ySec: number[];
let yMin: number[];
let lenSec: number;
let lenMin: number;
let lenHour: number;
let getSec: number;
let getMill: number;
let brightHour: number;
let cHours = [
  '#09235c', '#0a2561', '#0b2a70', '#1f4b99', '#f5c462', '#f56949',
  '#5ab6e0', '#60c7f0', '#41a9d9', '#73c7e6', '#2eb5e6', '#45abe6',
  '#46bceb', '#17afeb', '#45b0e6', '#4dc4ff', '#f56e62', '#f55249',
  '#4983f5', '#19448e', '#0b2a73', '#0a2561', '#17184b', '#17174a'
 ];

let plot: number = 4;
let plotR: number = 1.5;

let backCol = p5obj.color(255);
let diCol = p5obj.color(0);

let dNum: number = 10;
let dBoy_x: number[] = new Array(dNum).fill([]);
let dBoy_y: number[] = new Array(dNum).fill([]);
let off: number;
let thetaWav: number;

let dBoss_x: number;

let thetaRot: number;
let thetaSpi: number;

let rarity: number;

p5obj.setup = () =>  {
  p5obj.createCanvas(960, 480);

  getSec = p5obj.second();
  getMill = p5obj.millis();
  lenSec = 0;
  lenMin = 0;
  lenHour = 0;
  brightHour = 0;

  x = new Array(p5obj.width*plot);
  ySec = new Array(p5obj.width*plot);
  yMin = new Array(p5obj.width*plot);

  let theta: number = 0;
  for (let i: number = 0; i<p5obj.width*plot; i++) {
    x[i] = i/plot;
    ySec[i] = p5obj.sin(theta)*30;
    yMin[i] = p5obj.sin(p5obj.PI+0.1*theta)*180;
    theta += p5obj.PI/64;
  }

  for (let i: number = 0; i<10; i++) {
    dBoy_x[i] = p5obj.width;
    dBoy_y[i] = 0;
  }
  off = 0;
  thetaWav = 0;

  dBoss_x = 1.4*p5obj.width;

  thetaRot = 0;
  thetaSpi = 20;

  rarity = 0;
}

p5obj.draw = () =>  {

  /* 譎りｨ域悽菴薙・謠冗判 */
  drawHours();
  drawRules();
  drawMin();
  drawSec();

  /* 譎ょｱ繧､繝吶Φ繝・*/
  eventHour();

  /* 螟画焚縺ｮ遒ｺ隱咲畑 */
  // checkVars();
}



/* 譎る俣縺ｮ謠冗判 */
const drawHours = () => {

  /* 閭梧勹 */
  brightHour = p5obj.abs(p5obj.sin((p5obj.hour())*p5obj.PI/24))*255;
  p5obj.background(brightHour);

  /* 譎る俣縺ｮ遏ｩ蠖｢ */
  lenHour = p5obj.hour()*40+p5obj.minute()*40/60;
  p5obj.noStroke();
  p5obj.fill(cHours[p5obj.hour()]);
  p5obj.rect(0, 0, lenHour, p5obj.height);
}

/* 蛻・・謠冗判 */
const drawMin = () => {

  lenMin = 16*p5obj.minute()+16*p5obj.second()/60;

  /* 蛻・・髱｢ */
  p5obj.strokeWeight(1);
  p5obj.stroke(45+(255-brightHour)/2);
  for (let i: number = 0; i<lenMin*plot; i++) {
    p5obj.line(x[i], p5obj.height/2, x[i], yMin[i]+p5obj.height/2);
  }

  /* 蛻・・邱・*/
  for (let i: number = 0; i<p5obj.width*plot; i++) {
    p5obj.ellipse(x[i], yMin[i]+p5obj.height/2, plotR, plotR);
  }
}


/* 遘偵・謠冗判 */
const drawSec = () => {

  /* 繧ｰ繝ｩ繝輔′遘偵・蛻・ｊ譖ｿ繧上ｊ縺九ｉ菴輔Α繝ｪ遘堤ｵ碁℃縺励◆縺九ｒ蜿門ｾ励☆繧・*/
  if (p5obj.abs(p5obj.second()-getSec)>0) {
    getSec = p5obj.second();
    getMill = p5obj.millis();
  }

  /* 遘偵・邨碁℃繧定ｷ晞屬縺ｫ螟画鋤縺吶ｋ */
  lenSec = 16*p5obj.second()+16*(p5obj.millis()-getMill)/1000;

  /* 遘偵・譖ｲ邱・*/
  p5obj.noStroke();
  p5obj.fill(175);
  for (let i: number = 0; i<lenSec*plot; i++) {
    p5obj.ellipse(x[i], ySec[i]+p5obj.height/2, plotR, plotR);
  }

  /* 遘偵・逶ｴ邱・*/
  p5obj.stroke(175, 175);
  p5obj.strokeWeight(2);
  p5obj.line(0, p5obj.height/2, lenSec, p5obj.height/2);
}


/* 鄂ｫ邱壹・謠冗判(10蛻・ｹ・ */
const drawRules = () => {
  p5obj.stroke(125, 125);
  p5obj.strokeWeight(0.5);
  for (let i: number = 1; i<6; i++) {
    p5obj.line(i*160, 0, i*160, p5obj.height);
  }
}


/* 螟画焚縺ｮ蛟､繧堤｢ｺ隱阪☆繧九◆繧√・髢｢謨ｰ */
const checkVars = () => {
  p5obj.fill(175);
  p5obj.textSize(15);
  p5obj.text(p5obj.hour()+":"+p5obj.minute()+":"+p5obj.second(), 10, 20);
  p5obj.text(p5obj.frameRate+" fps", 10, 40);
  p5obj.text(p5obj.frameCount+" frames", 10, 60);
  p5obj.text(p5obj.millis()+" ms", 10, 80);
  p5obj.text(lenMin/16+" min.", 10, 100);
  p5obj.text(p5obj.second()+" sec.", lenSec, p5obj.height/2-20);
}


const eventHour = () => {

  /* 繧､繝吶Φ繝育匱逕・遘貞燕縺ｮ繧ｫ繧ｦ繝ｳ繝医ｒ謠冗判縺吶ｋ */
  if (p5obj.minute() == 59 && p5obj.second() > 56) {
    p5obj.fill(255, 255*(p5obj.millis()-getMill)/1000);
    p5obj.rect(0, 0, p5obj.width, p5obj.height);

    /* 譎ょｱ繧､繝吶Φ繝医↓逕ｨ縺・ｋ螟画焚繧貞・譛溷喧縺吶ｋ */

    // dBoyWave()
    for (let i: number = 0; i<10; i++) {
      dBoy_x[i] = p5obj.width;
      dBoy_y[i] = 0;
    }

    // dBoyBoss()
    dBoss_x = 1.4*p5obj.width;

    // dBoySpiral()
    thetaRot = 0;
    thetaSpi = 20;

    /* 譎ょｱ繧､繝吶Φ繝医・遒ｺ邇・*/
    rarity = p5obj.random(5);
  }


  if (p5obj.minute() >= 0 && p5obj.minute() <= 3) {
    if (rarity < 2) {
      dBoyWave();
    } else if (rarity < 4) {
      dBoyBoss();
    } else {
      dBoySpiral();
    }
  }
}

/* 譎ょｱ繧､繝吶Φ繝・ */
const dBoyWave = () => {
  diCol = p5obj.color(0);
  backCol = p5obj.color(255);

  for (let i: number = 0; i<10; i++) {
    dBoy_x[i] -= p5obj.noise(off)*2*(i+10);
    dBoy_y[i] = p5obj.sin(thetaWav+i*p5obj.PI/8)*70+50*(i+1);
  }

  for (let i: number = 0; i<10; i++) {
    p5obj.push();
    p5obj.translate(dBoy_x[i], dBoy_y[i]);
    p5obj.rotate(thetaWav);

    dBoy(0, 0, 50);
    p5obj.push();
  }

  thetaWav += 0.1;
  off += 0.01;
}

/* 譎ょｱ繧､繝吶Φ繝・ */
const dBoyBoss = () => {
  diCol = p5obj.color(0);
  backCol = p5obj.color(255);
  dBoy(dBoss_x, p5obj.height*3/7, p5obj.width*0.8);
  dBoss_x -= 5;
}

/* 譎ょｱ繧､繝吶Φ繝・ */
const dBoySpiral = () => {
  p5obj.push();
  p5obj.translate(p5obj.width/2, p5obj.height/2);
  p5obj.rotate(-thetaRot);

  for (let i: number = 0; i<1000; i++) {
    diCol = p5obj.color(p5obj.random(255), p5obj.random(255), p5obj.random(255));
    backCol = p5obj.color(p5obj.random(255), p5obj.random(255), p5obj.random(255));
    dBoy((i+1)*p5obj.pow(thetaSpi, 2)*p5obj.cos(thetaSpi-i*10), (i+1)*p5obj.pow(thetaSpi, 2)*p5obj.sin(thetaSpi-i*10), 50);
  }
  p5obj.push();

  thetaSpi -= 0.05;
  thetaRot += 0.07;
}


/* 繝・ュ縺上ｓ繧呈緒逕ｻ縺吶ｋ */
const dBoy = (x:number, y: number, size: number) => {

  p5obj.fill(diCol);
  p5obj.noStroke();

  // 縺励▲縺ｽ
  p5obj.fill(diCol);
  p5obj.beginShape();
  p5obj.vertex(x+size*0.11, y-size*0.2);
  p5obj.bezierVertex(x+size*0.5, y-size*0.05, x-size*0.1, y-size*0.5, x+size*0.4, y-size*0.51);
  p5obj.bezierVertex(x+size*0.35, y-size*0.5, x+size*0.35, y-size*0.175, x+size*0.4, y-size*0.2);
  p5obj.endShape(p5obj.CLOSE);

  // 縺九ｉ縺
  p5obj.fill(diCol);
  p5obj.ellipse(x, y, size*1, size*0.75);

  //縺医′縺・
  p5obj.fill(backCol);
  p5obj.ellipse(x, y-size*0.02, size*0.4, size*0.55);

  // 縺ｲ縺ｨ縺､繧・
  p5obj.fill(diCol);
  p5obj.ellipse(x, y-size*0.2, size*0.2, size*0.2);
  p5obj.fill(diCol);
  p5obj.ellipse(x, y-size*0.07, size*0.6, size*0.45);
  p5obj.fill(backCol);
  p5obj.ellipse(x, y-size*0.05, size*0.3, size*0.2);
}

};

export default sketch;
